{
  "nodes": {
    "Triggers": {
      "score": 1,
      "explanation": "The client identifies external cues that activate distress, especially noises and being in the room/window setting.",
      "quote": "\"sitting by the window and every little noise keeps making me think something bad is gonna happen\""
    },
    "Negative_Appraisals": {
      "score": 1,
      "explanation": "The client expresses maladaptive interpretations about danger and safety, such as believing they cannot stop something bad or that missing something will lead to harm.",
      "quote": "[\"feels like any second something could go wrong and i wont be able to stop it so i keep seeing those awful snapshots and cant relax\", \"i know i’m shutting everyone out but it feels like the only way to stay safe\", \"i gotta keep scanning because stopping feels unsafe\", \"if i do something bad will happen and ill just freeze\", \"if i miss something ill get caught off guard\"]"
    },
    "Memory": {
      "score": 1,
      "explanation": "The client describes intrusive images/snapshots and a reliving experience, indicating intrusive trauma memory or strong sensory recall.",
      "quote": "[\"so i keep seeing those awful snapshots and cant relax\", \"those sharp little pictures keep popping up and i just wanna shut everything out\", \"feels like its happening all over again\"]"
    },
    "Threat": {
      "score": 1,
      "explanation": "There is a clear ongoing sense of current danger and hypervigilance, including scanning for threats and fearing being caught off guard.",
      "quote": "[\"every little noise keeps making me think something bad is gonna happen\", \"i’m so tense like i have to watch everything or something bad will catch me off guard\", \"cant stop watching the door and dark corners\", \"stopping feels unsafe\", \"i cant even relax for a second bc i feel like if i do something bad will happen and ill just freeze\"]"
    },
    "Maladaptive_Strategies": {
      "score": 1,
      "explanation": "The client describes avoidance, shutting things out, and repeated checking/scanning as coping strategies that reduce distress short-term but maintain it.",
      "quote": "[\"i just wanna shut everything out\", \"i have to watch everything\", \"cant stop watching the door and dark corners\", \"i gotta keep scanning because stopping feels unsafe\", \"i just want to stay busy and not feel anything bc the fear gets louder when i stop\", \"i cant stop checking everything around me\", \"always checking the room esp the doors and windows\"]"
    }
  },
  "edges": {
